package com.configmonitor.app;
import org.junit.Test;
import static org.junit.Assert.*;
import org.json.*;
import java.io.*;
import java.net.*;
import java.nio.charset.StandardCharsets;
public class EgressTest {
 String response(String text)throws Exception{return EgressResponse.read(new ByteArrayInputStream(text.getBytes(StandardCharsets.US_ASCII)));}
 @Test public void contentLengthAndEof()throws Exception{assertEquals("8.8.8.8",response("HTTP/1.1 200 OK\r\nContent-Length: 7\r\n\r\n8.8.8.8"));assertEquals("1.1.1.1",response("HTTP/1.0 200 OK\r\n\r\n1.1.1.1\n"));}
 @Test public void chunkedBody()throws Exception{assertEquals("8.8.8.8",response("HTTP/1.1 200 OK\r\nTransfer-Encoding: chunked\r\n\r\n3;ext=x\r\n8.8\r\n4\r\n.8.8\r\n0\r\n\r\n"));}
 @Test public void ipv6()throws Exception{assertEquals(InetAddress.getByName("2606:4700:4700::1111").getHostAddress(),EgressResponse.literal("2606:4700:4700::1111"));}
 @Test public void rejectNonPublicAndHostnames(){for(String s:new String[]{"127.0.0.1","10.1.2.3","172.16.1.1","192.168.1.1","100.64.0.1","169.254.1.1","::1","fc00::1","fe80::1","api.ipify.org","8.8","8.8.8.999","2606:4700::1%eth0","https://8.8.8.8"})assertThrows(s,Exception.class,()->EgressResponse.literal(s));}
 @Test public void rejectRedirectsErrorAndUnexpectedBodies(){for(String s:new String[]{"HTTP/1.1 302 Found\r\nLocation: https://example.com\r\n\r\n","HTTP/1.1 403 Forbidden\r\n\r\n8.8.8.8","HTTP/1.1 200 OK\r\nContent-Length: 999\r\n\r\n","HTTP/1.1 200 OK\r\nContent-Encoding: gzip\r\n\r\n","HTTP/1.1 200 OK\r\nContent-Length: 7\r\n\r\n8.8","HTTP/1.1 200 OK\r\n\r\n<html>blocked</html>"})assertThrows(Exception.class,()->response(s));}
 JSONObject node(String engine)throws Exception{return new JSONObject().put("id",1).put("type","config").put("enabled",true).put("engine",engine).put("host","iran-entry.example").put("config",new JSONObject().put("type","wireguard").put("tag","original"));}
 @Test public void xrayHasOnlySelectedOutboundAndAuthenticatedLocalInbound()throws Exception{JSONObject n=node("xray"),c=EgressProbe.config(n,14000,"secret");assertEquals(1,c.getJSONArray("outbounds").length());assertEquals("egress",c.getJSONArray("outbounds").getJSONObject(0).getString("tag"));assertEquals("original",n.getJSONObject("config").getString("tag"));JSONObject in=c.getJSONArray("inbounds").getJSONObject(0);assertEquals("127.0.0.1",in.getString("listen"));assertEquals("password",in.getJSONObject("settings").getString("auth"));assertFalse(in.getJSONObject("settings").getBoolean("udp"));}
 @Test public void singboxHasNoDirectFallback()throws Exception{JSONObject c=EgressProbe.config(node("singbox"),14001,"secret");assertEquals(1,c.getJSONArray("outbounds").length());assertEquals("egress",c.getJSONObject("route").getString("final"));assertEquals("127.0.0.1",c.getJSONArray("inbounds").getJSONObject(0).getString("listen"));assertEquals("secret",c.getJSONArray("inbounds").getJSONObject(0).getJSONArray("users").getJSONObject(0).getString("password"));assertThrows(Exception.class,()->EgressProbe.config(node("other"),14000,"secret"));}
 @Test public void remoteDomainSentToSocksAndAuthRequired()throws Exception{ByteArrayOutputStream sent=new ByteArrayOutputStream();Socket fake=new Socket(){public void setSoTimeout(int ms){}public InputStream getInputStream(){return new ByteArrayInputStream(new byte[]{5,2,1,0,5,0,0,1,0,0,0,0,0,0});}public OutputStream getOutputStream(){return sent;}};EgressProbe.connectSocks(fake,"secret","api64.ipify.org",443);byte[] b=sent.toByteArray();assertEquals(2,b[2]);assertTrue(new String(b,StandardCharsets.US_ASCII).contains("api64.ipify.org"));assertEquals(1,b[b.length-2]);assertEquals(187,b[b.length-1]&255);Socket rejected=new Socket(){public void setSoTimeout(int ms){}public InputStream getInputStream(){return new ByteArrayInputStream(new byte[]{5,0});}public OutputStream getOutputStream(){return new ByteArrayOutputStream();}};assertThrows(IOException.class,()->EgressProbe.connectSocks(rejected,"secret","api64.ipify.org",443));}
 @Test public void separateRetryAndRefreshCadence()throws Exception{JSONObject n=node("xray").put("egressAttemptAt",1000000).put("egressState","ok");assertFalse(EgressLookup.due(n,1599999,false));assertTrue(EgressLookup.due(n,1600000,false));assertTrue(EgressLookup.due(n,1000001,true));n.put("egressState","unknown");assertFalse(EgressLookup.due(n,1119999,false));assertTrue(EgressLookup.due(n,1120000,false));n.put("enabled",false);assertFalse(EgressLookup.due(n,2000000,true));assertFalse(EgressLookup.due(null,2000000,true));}
 @Test public void entryCountryNeverUsedForConfig()throws Exception{JSONObject n=node("xray").put("countryCode","IR");CountryLookup.cache.put(n.getString("host"),new CountryLookup.Entry("IR",Long.MAX_VALUE));CountryLookup.decorate(n);assertEquals("",n.getString("countryCode"));assertFalse(CountryLookup.pending.contains(n.getString("host")));}
 @Test public void sameEntryCanHaveDifferentExitCountries()throws Exception{JSONObject a=node("xray").put("exitIp","8.8.8.8").put("egressAt",1).put("countryCode","US"),b=node("singbox").put("id",2).put("exitIp","1.1.1.1").put("egressAt",1).put("countryCode","AU");CountryLookup.decorate(a);CountryLookup.decorate(b);assertEquals("United States",a.getString("countryEn"));assertEquals("Australia",b.getString("countryEn"));}
 @Test public void abandonedCheckMarkedStaleWithoutLosingExit()throws Exception{JSONObject n=node("xray").put("egressAt",1).put("exitIp","8.8.8.8").put("countryCode","US").put("egressState","checking");CountryLookup.decorate(n);assertEquals("stale",n.getString("egressState"));assertEquals("US",n.getString("countryCode"));}
}
